<?php declare(strict_types=1);
$cdt=static fn(string $text):string=>\Kulturhus\Native\Language\ContributionDeliveryMessages::text($text,$contributiondeliveryMessages);
$cdStatuses=['pending'=>'Vorgemerkt','sending'=>'Versand läuft – Ergebnis ausstehend','sent'=>'Versendet','uncertain'=>'Versandergebnis prüfen','skipped'=>'Übersprungen'];
$cdRaw=static fn(string $name,string $default=''):string=>is_string($_GET[$name]??$default)?($_GET[$name]??$default):'';
$cdField=static function(string $name,string $value)use($cdt):void{if(strpbrk($value,"\r\n")!==false):?><textarea class="form-control" name="<?=e($name)?>"><?="\n".e($value)?></textarea><?php else:?><input class="form-control" name="<?=e($name)?>" value="<?=e($value)?>"><?php endif;};
?>
<section class="card" data-contributionmail-list><h2><?=e($cdt('Beitragsmails'))?></h2><p><?=e($cdt('Hier siehst du den aktuellen Versandstatus der freigegebenen Beitragsmails.'))?></p>
<?php foreach($contributiondeliveryState['errors']??[]as$failure):if($cdt($failure)!==$error):?><p role="alert"><?=e($cdt($failure))?></p><?php endif;endforeach ?>
<form method="get" class="general-settings-page-form" novalidate><?=hidden('view','finance').hidden('tab','contribution-mails').hidden('contributionmail_page','1')?>
<label><?=e($cdt('Beitragsmails suchen'))?><?php $cdField('contributionmail_q',$cdRaw('contributionmail_q'));?></label>
<label><?=e($cdt('Versandstatus'))?><select class="form-control" name="contributionmail_status"><option value=""><?=e($cdt('Alle Versandstatus'))?></option><?php $selected=$cdRaw('contributionmail_status');if($selected!==''&&!isset($cdStatuses[$selected])):?><option selected value="<?=e($selected)?>"><?=e($selected)?></option><?php endif;foreach($cdStatuses as$value=>$label):?><option value="<?=e($value)?>"<?=$selected===$value?' selected':''?>><?=e($cdt($label))?></option><?php endforeach ?></select></label>
<label><?=e($cdt('Beitragsjahr, leer für alle Jahre'))?><?php $cdField('contributionmail_year',$cdRaw('contributionmail_year'));?></label><button class="btn btn-outline theme-secondary"><?=e($cdt('Filter anwenden'))?></button></form>
<?php if($list=$contributiondeliveryState['listing']??null):?><p><?=e($cdt('Nachrichten'))?>: <?=e((string)$list['total'])?></p>
<?php foreach($list['rows']as$row):?><article class="card" data-contributionmail-job="<?=e($row['id'])?>"><h3><?=e($row['recipient_email'])?></h3><p><?=e($cdt($row['type']==='invoice'?'Jahresbeitragsrechnung':'Zahlungserinnerung'))?> · <?=e((string)$row['year'])?></p><p><?=e($cdt($cdStatuses[$row['status']]??$row['status']))?></p><?php if($row['reason']!==''):?><pre><?=e(\Kulturhus\Native\Language\ContributionDeliveryMessages::reason($row['reason'],$contributiondeliveryMessages))?></pre><?php endif ?><a class="btn btn-outline theme-secondary" href="<?=e(url(['view'=>'finance','tab'=>'contribution-mails','contributionmail_job'=>$row['id']]))?>"><?=e($cdt('Nachricht und Versand öffnen'))?></a></article><?php endforeach ?><?php if($list['total']===0):?><p><?=e($cdt('Keine Beitragsmailaufträge für diese Auswahl.'))?></p><?php endif;endif ?>
<?php if($list):$mailPage=$list['page'];$mailPages=$list['pages'];$mailQuery=['contributionmail_q'=>$cdRaw('contributionmail_q'),'contributionmail_status'=>$cdRaw('contributionmail_status'),'contributionmail_year'=>$cdRaw('contributionmail_year')]; ?><nav class="general-settings-actions" aria-label="<?=e($cdt('Nachrichtenseiten'))?>">
<?php if($mailPage!==null&&$mailPage>1): ?><a class="btn btn-outline theme-secondary" href="<?=e(url(['view'=>'finance','tab'=>'contribution-mails']+$mailQuery+['contributionmail_page'=>(string)($mailPage-1)]))?>"><?=e($cdt('Zurück'))?></a><?php endif ?>
<?php if($mailPage!==null): ?><span><?=e($cdt('Seite'))?> <?=e((string)$mailPage)?> / <?=e((string)$mailPages)?></span><?php endif ?>
<?php if($mailPage!==null&&$mailPage<$mailPages): ?><a class="btn btn-outline theme-secondary" href="<?=e(url(['view'=>'finance','tab'=>'contribution-mails']+$mailQuery+['contributionmail_page'=>(string)($mailPage+1)]))?>"><?=e($cdt('Weiter'))?></a><?php elseif($mailPage===null): ?><a class="btn btn-outline theme-secondary" href="<?=e(url(['view'=>'finance','tab'=>'contribution-mails']+$mailQuery+['contributionmail_page'=>'1']))?>"><?=e($cdt('Erste Seite öffnen'))?></a><?php endif ?></nav><?php endif ?>
</section>
